const $=s=>document.querySelector(s);const app=$('#app');const icon=n=>`<img src="assets/icons/${n}.svg" alt="">`;const money=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(n);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const read=(key,def)=>{try{return JSON.parse(localStorage.getItem(key))||def}catch{return def}};const imageMap={'necklace.jpg': 'ori-model-styling-v3.webp', 'hero.jpg': 'ori-twist-studio.webp', 'ring.jpg': 'ori-vow-studio.webp', 'beads.jpg': 'ori-heirloom-studio.webp'};let bag=read('ori-bag',[]).map(x=>({...x,image:imageMap[x.image]||x.image})),saved=read('ori-saved',[]),profile=read('ori-profile',null);let filter='All pieces',sort='featured',qty=1,finish='Gold',size='Medium';const products=[{id:'twist',name:'The Twist Hoops',category:'Earrings',price:28500,image:'ori-twist-studio.webp',label:'Bestseller',material:'Gold tone · Sculptural',desc:'An everyday pair with a little more character. A softly twisted silhouette catches the light from every angle.',details:'Gold-tone brass. Hinged closure. Approximate diameter: 25 mm.'},{id:'muse',name:'The Muse Layers',category:'Necklaces',price:42000,image:'ori-model-styling-v3.webp',label:'New arrival',material:'Gold tone · Layered',desc:'Two delicate chains, one effortless composition. A little shine at the collarbone, made for your favourite neckline.',details:'Gold-tone layered chains with an oval pendant. Adjustable length: 40–45 cm.'},{id:'vow',name:'The Vow Ring',category:'Rings',price:36000,image:'ori-vow-studio.webp',label:'A little forever',material:'Gold tone · Crystal',desc:'A slender band and a single luminous centre. A timeless shape to mark a moment, or simply make an ordinary day special.',details:'Gold-tone band with an oval clear crystal stone. Ring sizes shown in US sizing.'},{id:'heirloom',name:'The Heirloom Pearls',category:'Beads',price:48000,image:'ori-heirloom-studio.webp',label:'For the collector',material:'Pearl beads · Gold details',desc:'An expressive strand with an heirloom spirit. Wear it on its own, or layer it with a piece that already feels like you.',details:'Cream pearl-style beads with three gold-tone spacers and a clasp.'},{id:'sol',name:'The Sol Studs',category:'Earrings',price:31500,image:'ori-sol-studio.webp',material:'Gold tone · Everyday',desc:'A pair of folded gold petals with a softly curved edge. Small enough for daily wear, with a little sculptural volume.',details:'Gold-tone petal studs with butterfly backs.'},{id:'lumi',name:'The Lumi Pendant',category:'Necklaces',price:39500,image:'ori-lumi-studio.webp',material:'Gold tone · Delicate',desc:'A delicate pendant, suspended on a fine chain. Quiet enough for every day, beautiful enough for a special one.',details:'Gold-tone chain with a pendant and extender clasp.'}];
