bag=bag.map(x=>{const p=products.find(p=>p.id===x.id);return p?{...x,name:p.name,image:p.image,material:p.material}:x});
function persist(){localStorage.setItem('ori-bag',JSON.stringify(bag));localStorage.setItem('ori-saved',JSON.stringify(saved));$('#bagCount').textContent=bag.reduce((n,p)=>n+p.qty,0)}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}function card(p){return `<article class="product"><div class="product-image"><a href="#product/${p.id}" aria-label="View ${p.name}"><img src="assets/${p.image}" alt="${p.name}" loading="lazy"></a><button class="wish ${saved.includes(p.id)?'selected':''}" data-wish="${p.id}" aria-label="${saved.includes(p.id)?'Remove':'Save'} ${p.name}" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button></div><div class="product-info"><a href="#product/${p.id}"><h3>${p.name}</h3></a><p class="product-material">${p.material}</p><p class="price">${money(p.price)}</p></div></article>`}function chips(active){return `<div class="chips" aria-label="Product categories">${['All pieces','Necklaces','Earrings','Rings','Beads'].map(x=>`<button class="chip ${active===x?'active':''}" data-filter="${x}" aria-pressed="${active===x}">${x}</button>`).join('')}</div>`}function empty(title,text,ic='heart'){return `<div class="empty">${icon(ic)}<h2>${title}</h2><p>${text}</p><a class="primary" href="#shop">Explore the collection</a></div>`}

const editorialSlides=[
 ['ori-model-gold-v3.webp','Model in copper silk wearing sculptural gold hoops','Gold, in good company.','#shop/Earrings'],
 ['ori-lumi-studio.webp','Delicate gold oval pendant on a fine chain','A finer detail.','#product/lumi'],
 ['ori-model-pearls-v3.webp','Model wearing a pearl necklace with gold details','Pearls with presence.','#shop/Beads'],
 ['ori-sol-studio.webp','Sculptural gold petal studs','Small forms. Strong character.','#product/sol'],
 ['ori-carousel-details.webp','Gold ring and petal earrings styled on ivory linen','The finishing touch.','#shop'],
 ['ori-model-styling-v3.webp','Studio model wearing layered gold chains and an ivory silk blouse','Layers to live in.','#shop/Necklaces']
];
function editorialCarousel(){const slides=copy=>editorialSlides.map(([image,alt,title,href])=>`<${copy?'div':'a'} ${copy?'':`href="${href}"`} class="editorial-slide"><img src="assets/${image}" alt="${copy?'':alt}" loading="lazy" width="640" height="800"><span>${title}</span></${copy?'div':'a'}>`).join('');return `<section class="editorial-carousel" aria-label="The Orí lookbook"><div class="section-head"><div><p class="section-kicker">THE LOOKBOOK</p><h2>More ways to wear Orí.</h2></div><button type="button" class="secondary carousel-toggle" data-carousel-toggle aria-pressed="false">Pause carousel</button></div><div class="carousel-window" tabindex="0" aria-label="Scrolling lookbook. Pause to explore the photographs."><div class="carousel-track"><div class="carousel-group">${slides(false)}</div><div class="carousel-group carousel-copy" aria-hidden="true" inert>${slides(true)}</div></div></div><p class="lookbook-note">Explore the pieces behind each photograph.</p></section>`}

function homeCollections(){return ['Rings','Necklaces','Earrings','Beads'].map(category=>{const label=category==='Beads'?'Pearls & beads':category;return `<section class="collection category-shelf"><div class="section-head"><div><p class="section-kicker">THE COLLECTION · 6 DESIGNS</p><h2>${label}</h2></div><a class="text-link" href="#shop/${category}">Shop ${category==='Beads'?'beads':category.toLowerCase()}</a></div><div class="products">${products.filter(p=>p.category===category).map(card).join('')}</div></section>`}).join('')}
function stylistBanner(){return `<section class="stylist-banner"><div><span class="stylist-badge">ORÍ AI STYLIST · PREVIEW</span><h2>Your occasion. Your edit.</h2><p>Find a jewellery combination for your style and budget.</p></div><button class="primary" data-stylist>Find my edit</button></section>`}
function home(){return `<div class="mobile-intro mobile-only"><p>THE COLLECTION</p><h1>Discover Orí</h1></div><div class="mobile-category-row mobile-only"><a href="#shop">All pieces</a><a href="#shop/Earrings">Earrings</a><a href="#shop/Necklaces">Necklaces</a><a href="#shop/Beads">Pearls</a><a href="#shop/Rings">Rings</a></div><section class="hero"><div class="hero-copy"><p class="eyebrow">THE NEW COLLECTION</p><h1>The gold<br>& pearl edit.</h1><p>Sculptural earrings, fine chains, and pearl strands.<br>24 pieces. A collection to make your own.</p><a class="primary" href="#shop">Shop the collection</a></div><div class="hero-art"><img class="hero-main" src="assets/ori-model-hero-v3.webp" alt="Studio campaign portrait of a model wearing gold hoops and a fine pendant necklace" fetchpriority="high"><div class="mobile-hero-copy mobile-only"><span>THE NEW COLLECTION</span><h2>The gold edit.</h2><a href="#shop" class="hero-mobile-link">Explore the collection</a></div></div></section>${stylistBanner()}${editorialCarousel()}${homeCollections()}<section class="category-section"><div class="section-head"><h2>Find your form</h2></div><div class="category-grid"><a href="#shop/Earrings" class="category-tile"><img src="assets/ori-sol-studio.webp" alt="Sculptural gold petal earrings" loading="lazy"><div><h3>Earrings</h3><span class="category-action">Shop earrings</span></div></a><a href="#shop/Necklaces" class="category-tile"><img src="assets/ori-lumi-studio.webp" alt="Fine gold chain with an oval pendant" loading="lazy"><div><h3>Necklaces</h3><span class="category-action">Shop necklaces</span></div></a><a href="#shop/Beads" class="category-tile"><img src="assets/ori-heirloom-studio.webp" alt="Pearl strand with gold spacers" loading="lazy"><div><h3>Pearls & beads</h3><span class="category-action">Shop pearls</span></div></a></div></section><section class="story"><div class="story-media"><img src="assets/ori-model-styling-v3.webp" alt="Studio model wearing fine gold necklaces with an ivory silk blouse" loading="lazy"></div><div class="story-text"><p class="section-kicker">A NOTE ON STYLING</p><h2>A fine line.<br>A different feeling.</h2><p>A short chain and a longer pendant. Together, or on their own. Start with one piece and find the balance that feels right.</p><a class="text-link" href="#shop/Necklaces">Explore necklaces</a></div></section><section class="personal-section"><div><h2>A piece of your own.</h2><p>Choose your form, finish, and bead colour.</p></div><a class="secondary" href="#custom">Personalise a piece</a></section>`}
function shop(category='All pieces',query=''){filter=category;let list=products.filter(p=>(category==='All pieces'||p.category===category)&&(!query||`${p.name} ${p.category} ${p.material}`.toLowerCase().includes(query.toLowerCase())));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);return `<div class="page"><div class="page-heading"><p class="eyebrow">The collection</p><h1>${query?'Search results':category==='All pieces'?'The collection.':category}</h1><p>${query?`Results for “${esc(query)}”`:'Gold-tone jewellery, pearl strands, and fine layers.'}</p></div><div class="catalog-controls">${chips(category)}<select id="sort" aria-label="Sort products"><option value="featured" ${sort==='featured'?'selected':''}>Featured pieces</option><option value="low" ${sort==='low'?'selected':''}>Price: low to high</option><option value="high" ${sort==='high'?'selected':''}>Price: high to low</option></select></div><p style="color:var(--muted);font-size:11px;margin-bottom:20px">${list.length} pieces</p>${list.length?`<div class="products">${list.map(card).join('')}</div>`:empty('Nothing here just yet','Try another search, or explore all our pieces.','search')}</div>`}
function product(id){const p=products.find(x=>x.id===id);if(!p)return `<div class="page">${empty('Piece unavailable','Explore the rest of the collection.')}</div>`;let isRing=p.category==='Rings';return `<div class="page product-page"><div class="breadcrumb"><a href="#shop">Collection</a><span>/</span><a href="#shop/${p.category}">${p.category==='Beads'?'Pearls & beads':p.category}</a><span>/</span><span>${p.name}</span></div><div class="detail"><div class="detail-gallery"><img class="detail-picture" id="detailPicture" src="assets/${p.image}" alt="${p.name}">${['muse','lumi'].includes(p.id)?`<div class="gallery-controls"><button class="gallery-thumb active" data-photo="${p.image}" aria-label="Product photograph"><img src="assets/${p.image}" alt=""></button>${p.category==='Necklaces'?`<button class="gallery-thumb" data-photo="ori-model-hero-v3.webp" aria-label="Layering inspiration"><img src="assets/ori-model-hero-v3.webp" alt=""></button>`:''}<span>Product / Styling</span></div>`:''}</div><div class="detail-copy"><p class="section-kicker">${p.category==='Beads'?'PEARLS & BEADS':p.category.toUpperCase()}</p><h1>${p.name}</h1><p class="detail-material">${p.material}</p><p class="price">${money(p.price)}</p><p class="detail-description">${p.desc}</p><div class="material-row"><span>Finish</span><span class="finish-value"><i></i>Gold tone</span></div><span class="option-label">${isRing?'Choose ring size':'Length & fit'}</span>${isRing?`<div class="options">${['5','6','7','8','9'].map(x=>`<button data-size="${x}" class="option ${size===x?'active':''}" aria-pressed="${size===x}">${x}</button>`).join('')}</div><p class="detail-note">US ring sizes</p>`:`<div class="one-size">${p.category==='Necklaces'?'Adjustable chain':p.category==='Beads'?'Classic strand':'One size'}</div>`}<div class="add-row"><div class="quantity"><button data-qty="-1" aria-label="Decrease quantity">${icon('minus')}</button><span id="qty">${qty}</span><button data-qty="1" aria-label="Increase quantity">${icon('plus')}</button></div><button class="primary" data-add="${p.id}">Add to bag ${icon('shopping-bag')}</button></div><button class="save-product text-link" data-wish="${p.id}" aria-pressed="${saved.includes(p.id)}">${icon('heart')} ${saved.includes(p.id)?'Saved to your collection':'Save this piece'}</button><div class="detail-disclosures"><details open><summary>Details & materials</summary><p>${p.details}</p></details><details><summary>Care guide</summary><p>Keep your piece in a dry, soft-lined pouch. Avoid perfume and water. Wipe gently with a clean, dry cloth.</p></details><details><summary>Delivery & returns</summary><p>Delivery and returns will be confirmed when the store opens for orders. Checkout currently runs as a preview.</p></details></div></div></div><section class="collection recommendations"><div class="section-head"><h2>In the same collection</h2></div><div class="products">${products.filter(x=>x.id!==id&&x.category===p.category).slice(0,4).map(card).join('')}</div></section><div class="mobile-product-bar mobile-only"><div><span>Total</span><strong id="mobileProductTotal">${money(p.price*qty)}</strong></div><button class="primary" data-add="${p.id}">Add to bag ${icon('shopping-bag')}</button></div></div>`}
function bagPage(){if(!bag.length)return `<div class="page"><div class="page-heading"><h1>Your bag</h1></div>${empty('Your bag is empty.','Choose a piece from the collection to start.','shopping-bag')}</div>`;const total=bag.reduce((s,x)=>s+x.price*x.qty,0);return `<div class="page"><div class="page-heading"><h1>Your bag</h1><p>${bag.reduce((s,x)=>s+x.qty,0)} ${bag.reduce((s,x)=>s+x.qty,0)===1?'piece':'pieces'} in your bag</p></div><div class="bag-layout"><div>${bag.map((x,i)=>`<article class="bag-row"><img src="assets/${x.image}" alt="${esc(x.name)}"><div><h3>${esc(x.name)}</h3><p>${esc(x.finish)} · ${esc(x.size)}</p><div class="quantity"><button data-bag-qty="${i}" data-delta="-1" aria-label="Decrease ${esc(x.name)} quantity">${icon('minus')}</button><span>${x.qty}</span><button data-bag-qty="${i}" data-delta="1" aria-label="Increase ${esc(x.name)} quantity">${icon('plus')}</button></div><br><button data-remove="${i}" class="remove">Remove</button></div><span>${money(x.price*x.qty)}</span></article>`).join('')}<a href="#shop" class="text-link" style="margin-top:25px"> Continue exploring</a></div><aside class="summary-box"><h3>Order summary</h3><div class="summary-line"><span>Subtotal</span><span>${money(total)}</span></div><div class="summary-line"><span>Gift packaging</span><span>Included</span></div><div class="summary-line"><span>Delivery</span><span>Confirmed at launch</span></div><div class="summary-line summary-total"><span>Total</span><span>${money(total)}</span></div><a class="primary" href="#checkout">Continue to demo checkout</a><p>Demo storefront. No payment will be collected.</p></aside></div></div>`}
function account(){return `<div class="page"><div class="form-panel"><p class="eyebrow">YOUR DETAILS</p><h2>${profile?`Welcome, ${esc(profile.name.split(' ')[0])}.`:'Your Orí profile.'}</h2><p>${profile?'Your preferences are saved on this device.':'Save your details on this device for a more personal experience.'}</p><form id="profileForm"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" value="${profile?esc(profile.name):''}" required><label for="accountEmail">Email address</label><input id="accountEmail" type="email" name="email" autocomplete="email" value="${profile?esc(profile.email):''}" required><button class="primary">Save my details ${icon('check')}</button></form><div class="account-links"><a class="text-link" href="#saved">Saved pieces ${icon('heart')}</a><a class="text-link" href="#bag">Your bag ${icon('shopping-bag')}</a></div></div></div>`}
function checkout(){if(!bag.length)return bagPage();return `<div class="page"><div class="form-panel"><p class="eyebrow">The finishing touches</p><h2>Make it yours.</h2><p>Try the checkout flow. This is a demo: no order is sent and no payment is taken.</p><form id="checkoutForm"><label for="fullName">Full name</label><input id="fullName" name="name" autocomplete="name" value="${profile?esc(profile.name):''}" required><label for="checkoutEmail">Email address</label><input id="checkoutEmail" name="email" type="email" autocomplete="email" value="${profile?esc(profile.email):''}" required><label for="address">Delivery address</label><input id="address" name="address" autocomplete="street-address" required><div class="two-cols"><div><label for="city">City</label><input id="city" name="city" autocomplete="address-level2" required></div><div><label for="state">State</label><input id="state" name="state" autocomplete="address-level1" required></div></div><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" autocomplete="tel" required><div class="summary-line summary-total"><span>Demo total</span><span>${money(bag.reduce((s,x)=>s+x.price*x.qty,0))}</span></div><button class="primary">Complete demo checkout</button></form></div></div>`}
function atelier(){return `<div class="page"><div class="atelier-title"><p class="eyebrow">The Orí atelier</p><h1>A study in<br>everyday jewellery.</h1><p>Orí brings together 24 jewellery designs: six rings, six necklaces, six pairs of earrings, and six bead or pearl strands. Explore different forms, colours, and combinations.</p><a href="#shop" class="primary">Explore the collection</a></div><img class="atelier-image" src="assets/ori-twist-studio.webp" alt="Sculptural gold hoops photographed in natural light"><div class="values"><div><h3>Form</h3><p>Simple silhouettes with something unexpected. A twist, a curve, a detail that catches your eye.</p></div><div><h3>Wear</h3><p>A piece can mark a milestone, remind you of someone, or just feel right on an ordinary Tuesday.</p></div><div><h3>Personalise</h3><p>Layer what you love. Mix old and new. Create a piece with the colours and finishes that feel like you.</p></div></div><a href="#custom" class="secondary">Create your own piece</a></div>`}
function custom(){return `<div class="page"><div class="page-heading"><p class="eyebrow">PERSONALISE</p><h1>The personal collection.</h1><p>Build a custom concept and add it to your bag.</p></div><div class="custom-layout"><img id="customImage" src="assets/ori-heirloom-studio.webp" alt="Jewellery inspiration for a custom piece"><div class="form-panel"><h2>Your piece</h2><p>Choose the details below. Images are inspiration; your selections appear in the bag.</p><form id="customForm"><label for="customType">Start with a piece</label><select id="customType" name="type"><option>Beaded necklace</option><option>Layered necklace</option><option>Statement ring</option></select><label for="customMaterial">Choose a finish</label><select id="customMaterial" name="finish"><option>Warm gold</option><option>Cool silver</option></select><label for="customBead">Choose your accents</label><select id="customBead" name="bead"><option>Natural tones</option><option>Pearl white</option><option>Terracotta</option><option>Forest green</option></select><label for="customLength">Choose your length or size</label><select id="customLength" name="size"><option>Small</option><option selected>Medium</option><option>Large</option></select><label for="customNote">A personal note (optional)</label><input id="customNote" name="note" maxlength="80" placeholder="A name, a date, a little meaning"><div class="summary-line summary-total"><span>Your concept</span><span id="customPrice">${money(52000)}</span></div><button class="primary">Add custom piece to bag ${icon('shopping-bag')}</button></form></div></div></div>`}
function render(){let parts=location.hash.slice(1).split('/'),route=parts[0]||'home';let param=decodeURIComponent(parts.slice(1).join('/'));document.body.dataset.route=route;if(route==='product'){qty=1;finish='Gold';size=products.find(x=>x.id===param)?.category==='Rings'?'7':'One size'}app.innerHTML=route==='home'?home():route==='shop'?shop(param||'All pieces'):route==='search'?shop('All pieces',param):route==='product'?product(param):route==='bag'?bagPage():route==='saved'?`<div class="page"><div class="page-heading"><h1>Saved pieces.</h1><p>Your personal selection.</p></div>${saved.length?`<div class="products">${products.filter(x=>saved.includes(x.id)).map(card).join('')}</div>`:empty('Keep your favourites here.','Tap the heart on a piece to keep it here.')}</div>`:route==='account'?account():route==='checkout'?checkout():route==='atelier'?atelier():route==='custom'?custom():home();document.querySelectorAll('[data-tab]').forEach(a=>a.classList.toggle('active',a.dataset.tab===route||(a.dataset.tab==='shop'&&['product','search','custom'].includes(route))));persist();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-carousel-toggle')){const c=b.closest('.editorial-carousel');const paused=c.classList.toggle('is-paused');b.textContent=paused?'Play carousel':'Pause carousel';b.setAttribute('aria-pressed',String(paused))}if(b.hasAttribute('data-search')){$('#searchDialog').showModal();setTimeout(()=>$('#searchDialog input').focus(),30)}if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.wish){const id=b.dataset.wish;const had=saved.includes(id);saved=had?saved.filter(x=>x!==id):[...saved,id];persist();b.classList.toggle('selected',!had);b.setAttribute('aria-pressed',!had);b.setAttribute('aria-label',`${had?'Save':'Remove'} ${products.find(x=>x.id===id).name}`);toast(had?'Removed from saved pieces':'Saved pieces. Piece saved.');if(location.hash==='#saved')render()}if(b.dataset.filter){const route=b.dataset.filter==='All pieces'?'#shop':`#shop/${b.dataset.filter}`;if(location.hash===route)render();else location.hash=route}if(b.dataset.photo){$('#detailPicture').src='assets/'+b.dataset.photo;$('#detailPicture').alt=b.dataset.photo==='ori-model-hero-v3.webp'?'Layering inspiration':products.find(x=>x.id===location.hash.split('/')[1]).name;document.querySelectorAll('[data-photo]').forEach(x=>x.classList.toggle('active',x===b))}if(b.dataset.finish){finish=b.dataset.finish;$('#finishLabel').textContent=finish;document.querySelectorAll('[data-finish]').forEach(x=>{x.classList.toggle('active',x.dataset.finish===finish);x.setAttribute('aria-pressed',x.dataset.finish===finish)})}if(b.dataset.size){size=b.dataset.size;document.querySelectorAll('[data-size]').forEach(x=>{x.classList.toggle('active',x.dataset.size===size);x.setAttribute('aria-pressed',x.dataset.size===size)})}if(b.dataset.qty){qty=Math.max(1,Math.min(10,qty+Number(b.dataset.qty)));$('#qty').textContent=qty;if($('#mobileProductTotal'))$('#mobileProductTotal').textContent=money(products.find(p=>p.id===location.hash.split('/')[1]).price*qty)}if(b.dataset.add){const p=products.find(x=>x.id===b.dataset.add),existing=bag.find(x=>x.id===p.id&&x.finish===finish&&x.size===size);if(existing)existing.qty+=qty;else bag.push({...p,finish,size,qty});persist();toast(`${p.name} added to your bag`)}if(b.dataset.bagQty!==undefined){const i=Number(b.dataset.bagQty);bag[i].qty+=Number(b.dataset.delta);if(bag[i].qty<1)bag.splice(i,1);persist();render()}if(b.dataset.remove!==undefined){bag.splice(Number(b.dataset.remove),1);persist();render();toast('Piece removed from bag')}if(b.dataset.info){const info={care:['Jewellery care','Store each piece separately in a soft pouch. Avoid perfume, water, and harsh chemicals. Wipe gently with a clean, dry cloth.'],delivery:['Delivery & returns','This is a demonstration storefront. Delivery regions, fees, stock availability, and return policies will be added when the boutique launches.'],contact:['Contact Orí','Contact details will be added when the boutique launches. For now, explore the collection or save your favourite pieces.']}[b.dataset.info];$('#infoDialog').innerHTML=`<div class="dialog-head"><h2>${info[0]}</h2><button data-close aria-label="Close">${icon('x')}</button></div><p>${info[1]}</p>`;$('#infoDialog').showModal()}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;const parts=location.hash.slice(1).split('/');app.innerHTML=shop(parts[0]==='shop'?decodeURIComponent(parts[1]||'All pieces'):'All pieces',parts[0]==='search'?decodeURIComponent(parts[1]||''):'')}if(e.target.id==='customType'){const t=e.target.value;$('#customImage').src=`assets/${t==='Statement ring'?'ori-vow-studio.webp':t==='Layered necklace'?'ori-model-styling-v3.webp':'ori-heirloom-studio.webp'}`;$('#customPrice').textContent=money(t==='Statement ring'?46000:t==='Layered necklace'?58000:52000)}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f);if(f.id==='searchForm'){const q=data.get('query').trim();if(!q)return;$('#searchDialog').close();location.hash='#search/'+encodeURIComponent(q)}if(f.id==='newsletter'){toast('You’re on the list on this device.');localStorage.setItem('ori-newsletter',$('#email').value);f.reset()}if(f.id==='profileForm'){profile={name:data.get('name').trim(),email:data.get('email')};localStorage.setItem('ori-profile',JSON.stringify(profile));render();toast('Your details are saved on this device')}if(f.id==='customForm'){const type=data.get('type'),price=type==='Statement ring'?46000:type==='Layered necklace'?58000:52000;bag.push({id:'custom-'+Date.now(),name:'Your '+type.toLowerCase(),category:'Custom',image:type==='Statement ring'?'ori-vow-studio.webp':type==='Layered necklace'?'ori-model-styling-v3.webp':'ori-heirloom-studio.webp',price,finish:data.get('finish')+' · '+data.get('bead')+(data.get('note')?' · '+data.get('note'):''),size:data.get('size'),qty:1});persist();toast('Your personal edit is in the bag')}if(f.id==='checkoutForm'){app.innerHTML=`<div class="page"><div class="empty">${icon('check')}<p class="eyebrow">Demo checkout complete</p><h2>Order summary, ${esc(data.get('name').split(' ')[0])}.</h2><p>You have completed the preview. No order was placed and no payment was taken.<br>Your pieces are still in your bag.</p><a class="primary" href="#bag">Back to your bag ${icon('shopping-bag')}</a></div></div>`;window.scrollTo(0,0)}});window.addEventListener('hashchange',render);render();
